import{_ as t,o as r,c as a,a5 as n}from"./chunks/framework.bIR-4glx.js";const b=JSON.parse('{"title":"Artifact Brief and Delivery Card","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/artifact-brief.en.md","filePath":"public/downloads/worksheets/artifact-brief.en.md","lastUpdated":1795488252000}'),d={name:"public/downloads/worksheets/artifact-brief.en.md"};function i(o,e,s,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="artifact-brief-and-delivery-card" tabindex="-1">Artifact Brief and Delivery Card <a class="header-anchor" href="#artifact-brief-and-delivery-card" aria-label="Permalink to &quot;Artifact Brief and Delivery Card&quot;">​</a></h1><p>An artifact does not need to be complete on day one, but it needs boundaries on day one. Copy this card into a private project directory and keep the independent, revised, reviewed, and delivered versions. Do not include passwords, client data, unauthorised third-party information, or unnecessary personal details.</p><h2 id="_1-artifact-boundary" tabindex="-1">1. Artifact boundary <a class="header-anchor" href="#_1-artifact-boundary" aria-label="Permalink to &quot;1. Artifact boundary&quot;">​</a></h2><h3 id="artifact-brief-—-yyyy-mm-dd" tabindex="-1">Artifact Brief — YYYY-MM-DD <a class="header-anchor" href="#artifact-brief-—-yyyy-mm-dd" aria-label="Permalink to &quot;Artifact Brief — YYYY-MM-DD&quot;">​</a></h3><p>Artifact name:<br> Real situation:<br> Audience/user:<br> One problem to solve:</p><p>Inputs and sources:<br> My current baseline:<br> Key assumptions:</p><p>Smallest deliverable:<br> Format, time, and other constraints:<br> Acceptance criteria:<br> What this will not include:</p><p>First-version deadline:<br> Who will give feedback:<br> Evidence to preserve:<br> How to shrink, pause, or roll back:<br> Next review date:</p><h2 id="_2-four-versions" tabindex="-1">2. Four versions <a class="header-anchor" href="#_2-four-versions" aria-label="Permalink to &quot;2. Four versions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Completion condition</th><th>What to keep</th></tr></thead><tbody><tr><td>Independent</td><td>Complete the smallest action without an answer key or AI writing it</td><td>Original file, time, bottlenecks</td></tr><tr><td>Structure</td><td>Audience can find the problem, conclusion, and next step</td><td>Structural diff, fact/guess marks</td></tr><tr><td>Review</td><td>A real reader, user, peer, or defined AI reviewer completes a review</td><td>Feedback, error categories, accept/reject reasons</td></tr><tr><td>Delivery</td><td>Another person can begin without your oral explanation</td><td>Version, limits, sources, known issues, handover record</td></tr></tbody></table><h2 id="_3-quality-gates" tabindex="-1">3. Quality gates <a class="header-anchor" href="#_3-quality-gates" aria-label="Permalink to &quot;3. Quality gates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gate</th><th>Check</th><th>Evidence location</th><th>Owner/date</th></tr></thead><tbody><tr><td>Clear</td><td>Does the audience know the problem and next action?</td><td></td><td></td></tr><tr><td>Accurate</td><td>Do facts, citations, code, and numbers return to a source or test?</td><td></td><td></td></tr><tr><td>Usable</td><td>Can the main action work under real constraints?</td><td></td><td></td></tr><tr><td>Maintainable</td><td>Are version, dependencies, limits, and owner visible?</td><td></td><td></td></tr><tr><td>Responsible</td><td>Are privacy, copyright, permissions, and error consequences handled?</td><td></td><td></td></tr></tbody></table><p>Write “unverified” when there is no evidence for a pass. Speed, word count, and feature count are proxy measures, not quality gates.</p><h2 id="_4-ai-and-feedback-record" tabindex="-1">4. AI and feedback record <a class="header-anchor" href="#_4-ai-and-feedback-record" aria-label="Permalink to &quot;4. AI and feedback record&quot;">​</a></h2><p>AI/tool and date:<br> Work it was allowed to do:<br> Human judgments I kept:<br> Three highest-impact issues it raised:<br> What I accepted/rejected, and why:<br> Main point restated by a real reader/user:<br> Most important repair:</p><p>Save your version first, then use AI to diagnose, simulate an audience, or generate a parallel task. A person confirms critical facts, permissions, privacy, cost, and final authorship.</p><h2 id="_5-delivery-and-rollback" tabindex="-1">5. Delivery and rollback <a class="header-anchor" href="#_5-delivery-and-rollback" aria-label="Permalink to &quot;5. Delivery and rollback&quot;">​</a></h2><p>Delivery audience and permission scope:<br> Delivery date and version:<br> Instructions:<br> Known limits:<br> Support owner/contact:<br> Cost and retention period:<br> Pause/degrade/rollback trigger:<br> Who must be notified after a problem:<br> Next review date:</p><p>Delivery is not the end. After 3–7 days, run a parallel test and record whether another person can start independently, what still needs explanation, and the one change for the next version.</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-3/4-artifacts-and-delivery" target="_blank" rel="noreferrer">Artifacts: Turn Learning into Something Made</a> | <a href="https://byoungd.github.io/up/en/templates/90-day-cycle" target="_blank" rel="noreferrer">90-Day Cycle Map</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/artifact-brief" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-08-31. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',22)])])}const u=t(d,[["render",i]]);export{b as __pageData,u as default};
